INSERT INTO `pos_store_reviews` (`id`, `tenant_id`, `reviewer_name`, `store_name`, `avatar_initials`, `rating`, `review_text`, `is_approved`, `is_featured`, `created_at`, `updated_at`) VALUES
	(1, 1, 'Aling Maria Santos', 'San Jose Minimart', 'MS', 5, 'Napakalaking tulong sa aming Minimart! Dati laging kulang ang benta sa hapon, ngayon kitang-kita sa audit log kung anong nangyari per shift.', 1, 1, '2026-08-21 14:58:40', '2026-08-21 14:58:40'),
	(2, 1, 'Mang Robert Cruz', 'R&M Grocery Store', 'RC', 5, 'Yung Utang CRM feature ang pinaka-favorite ko. Dati nawawala ang cuaderno sa utang, ngayon mabilis na mag-remind sa mga suki!', 1, 1, '2026-08-21 14:58:40', '2026-08-21 14:58:40'),
	(3, 1, 'Chef Liza Tan', 'Liza Retail Mart Chain', 'LT', 5, 'Subok na subok sa 3 branches namin! Madaling i-monitor ang inventory kahit nasa bahay lang ako gamit ang cellphone.', 1, 1, '2026-08-21 14:58:40', '2026-08-21 14:58:40'),
	(4, 1, 'Kuya Cardo Dalisay', 'Cardo Express Minimart', 'CD', 5, 'Super bilis ng barcode scanning sa POS terminal. Hindi na nag-aantay nang matagal ang mga mamimili tuwing rush hour!', 1, 1, '2026-08-21 14:58:40', '2026-08-21 14:58:40'),
	(5, NULL, 'Tiya Nena 6a8867d5652a7', 'Nena Sari-Sari Store', 'TN', 5, 'Napakadaling gamitin sa cellphone ko! Sobrang nakakatulong sa araw-araw na benta.', 1, 1, '2026-08-21 14:59:33', '2026-08-21 14:59:33');
